contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address _target, uint _value, uint _depositAmount) public payable {
        require(msg.sender != c.owner(), "caller must not be owner");
        require(_depositAmount <= address(this).balance, "not enough balance for deposit");

        uint depositsBefore = c.depositsCount();
        address(c).call{value: _depositAmount}("");
        uint depositsAfter = c.depositsCount();

        bool withdrawReverted;
        try c.withdraw(_value) { withdrawReverted = false; } catch { withdrawReverted = true; }

