contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(address target, uint value, uint depositAmount, uint withdrawAmount) public payable {
        require(address(this).balance >= value + depositAmount, "insufficient test balance");
        require(target != address(0) && target != address(c), "must be a regular external target");

        // Setup: fund c through the fallback so it has ether available for the payout.
        c.call{value: depositAmount}("");
        uint depositsBefore = c.depositsCount();

        // Observe the recipient's balance immediately before the sendMoney call.
        uint targetBalanceBefore = target.balance;

        // Exercise the sendMoney path.
        c.sendMoney(target, value);

        // General rule: the target's balance grows by exactly the requested value,
        // and the deposits counter is untouched by a payment that does not go through the fallback.
        assert(target.balance == targetBalanceBefore + value && c.depositsCount() == depositsBefore);
    }
}

